120	// CountCheckpointsInTree counts checkpoint shard directories in a /full/* tree.
121	// The tree structure is <id[:2]>/<id[2:]>/ — we count second-level directories
122	// across all shard prefixes. Returns 0 for an empty tree.
123	func (s *V2GitStore) CountCheckpointsInTree(treeHash plumbing.Hash) (int, error) {
124		if treeHash == plumbing.ZeroHash {
125			return 0, nil
126		}
127	
128		tree, err := s.repo.TreeObject(treeHash)
129		if err != nil {
130			return 0, fmt.Errorf("failed to read tree: %w", err)
131		}
132	
133		count := 0
134		if err := WalkCheckpointShards(s.repo, tree, func(_ id.CheckpointID, _ plumbing.Hash) error {
135			count++
136			return nil
137		}); err != nil {
138			return 0, err
139		}
140	
141		return count, nil
142	}
143	
144	// AddGenerationJSONToTree adds generation.json to an existing root tree, returning
145	// a new root tree hash. Preserves all existing entries (shard directories, etc.).
146	func (s *V2GitStore) AddGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
147		entry, err := s.marshalGenerationBlob(gen)
148		if err != nil {
149			return plumbing.ZeroHash, err
150		}
151	
152		return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
153			UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
154	}
