156	// ComputeGenerationCheckpointTimestamps derives timestamps from the checkpoints
157	// present in a /full/* tree. It prefers created_at from v2 /main metadata and
158	// falls back to top-level transcript event timestamps for older or partial v2 data.
159	func (s *V2GitStore) ComputeGenerationCheckpointTimestamps(rootTreeHash plumbing.Hash) (GenerationMetadata, bool, error) {
160		mainTree, mainTreeErr := s.v2MainTree()
161		if mainTreeErr != nil {
162			mainTree = nil
163		}
164		return s.ComputeGenerationTimestampsFromTrees(rootTreeHash, mainTree)
165	}
166	
167	// ComputeGenerationTimestampsFromTrees walks every checkpoint in rootTreeHash
168	// and aggregates per-checkpoint timestamps. When mainTree is non-nil, /main
169	// metadata.json is consulted before falling back to the raw transcript inside
170	// the checkpoint's full-tree. Returns found=false when any checkpoint cannot
171	// produce a timestamp; callers decide their own fallback (e.g. read existing
172	// generation.json, recompute from in-memory data, or surface an error).
173	func (s *V2GitStore) ComputeGenerationTimestampsFromTrees(rootTreeHash plumbing.Hash, mainTree *object.Tree) (GenerationMetadata, bool, error) {
174		if rootTreeHash == plumbing.ZeroHash {
175			return GenerationMetadata{}, false, nil
176		}
177	
178		rootTree, err := s.repo.TreeObject(rootTreeHash)
179		if err != nil {
180			return GenerationMetadata{}, false, fmt.Errorf("failed to read generation tree: %w", err)
181		}
182	
183		var gen GenerationMetadata
184		found := false
185		missingCheckpointTimestamp := false
186		err = WalkCheckpointShards(s.repo, rootTree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
187			if mainTree != nil {
188				if cpGen, ok := s.checkpointTimestampRangeFromMain(mainTree, cpID); ok {
189					mergeGenerationRange(&gen, &found, cpGen)
190					return nil
191				}
192			}
193	
194			cpTree, treeErr := s.repo.TreeObject(cpTreeHash)
195			if treeErr != nil {
196				missingCheckpointTimestamp = true
197				return nil //nolint:nilerr // Skip unreadable checkpoint trees and fall back to generation.json.
198			}
199			if cpGen, ok := checkpointTimestampRangeFromFullTree(cpTree); ok {
200				mergeGenerationRange(&gen, &found, cpGen)
201				return nil
202			}
203			missingCheckpointTimestamp = true
204			return nil
205		})
206		if err != nil {
207			return GenerationMetadata{}, false, err
208		}
209		if missingCheckpointTimestamp {
210			return GenerationMetadata{}, false, nil
211		}
212	
213		return gen, found, nil
214	}
215	
216	// computeGenerationTimestamps derives timestamps for a generation being archived.
217	// It uses checkpoint metadata/transcript timestamps rather than git commit times
218	// so migration and ref-repair commits don't reset retention age.
219	func (s *V2GitStore) computeGenerationTimestamps(rootTreeHash plumbing.Hash) GenerationMetadata {
220		if gen, ok, err := s.ComputeGenerationCheckpointTimestamps(rootTreeHash); err == nil && ok {
221			return gen
222		}
223		return s.computeGenerationTimestampsFromCommitHistory()
224	}
225	
226	func (s *V2GitStore) computeGenerationTimestampsFromCommitHistory() GenerationMetadata {
227		now := time.Now().UTC()
228		fallback := GenerationMetadata{OldestCheckpointAt: now, NewestCheckpointAt: now}
229	
230		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
231		ref, err := s.repo.Reference(refName, true)
232		if err != nil {
233			return fallback
234		}
235	
236		commit, err := s.repo.CommitObject(ref.Hash())
237		if err != nil {
238			return fallback
239		}
240	
241		newest := commit.Committer.When.UTC()
242	
243		// Walk parents to find the oldest commit in this generation
244		iter := commit
245		for len(iter.ParentHashes) > 0 {
246			parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
247			if parentErr != nil {
248				break
249			}
250			iter = parent
251		}
252		oldest := iter.Committer.When.UTC()
253	
254		return GenerationMetadata{
255			OldestCheckpointAt: oldest,
256			NewestCheckpointAt: newest,
257		}
258	}
