260	func (s *V2GitStore) v2MainTree() (*object.Tree, error) {
261		ref, err := s.repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
262		if err != nil {
263			return nil, fmt.Errorf("failed to read v2 main ref: %w", err)
264		}
265		commit, err := s.repo.CommitObject(ref.Hash())
266		if err != nil {
267			return nil, fmt.Errorf("failed to read v2 main commit: %w", err)
268		}
269		tree, err := commit.Tree()
270		if err != nil {
271			return nil, fmt.Errorf("failed to read v2 main tree: %w", err)
272		}
273		return tree, nil
274	}
275	
276	func (s *V2GitStore) checkpointTimestampRangeFromMain(mainTree *object.Tree, cpID id.CheckpointID) (GenerationMetadata, bool) {
277		cpTree, err := mainTree.Tree(cpID.Path())
278		if err != nil {
279			return GenerationMetadata{}, false
280		}
281	
282		var gen GenerationMetadata
283		found := false
284		for _, entry := range cpTree.Entries {
285			if entry.Mode != filemode.Dir {
286				continue
287			}
288			if _, err := strconv.Atoi(entry.Name); err != nil {
289				continue
290			}
291			sessionTree, err := s.repo.TreeObject(entry.Hash)
292			if err != nil {
293				continue
294			}
295			metadataFile, err := sessionTree.File(paths.MetadataFileName)
296			if err != nil {
297				continue
298			}
299			metadataContent, err := metadataFile.Contents()
300			if err != nil {
301				continue
302			}
303			var metadata CommittedMetadata
304			if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil || metadata.CreatedAt.IsZero() {
305				continue
306			}
307			MergeGenerationTime(&gen, &found, metadata.CreatedAt.UTC())
308		}
309		return gen, found
310	}
311	
312	func checkpointTimestampRangeFromFullTree(cpTree *object.Tree) (GenerationMetadata, bool) {
313		var gen GenerationMetadata
314		found := false
315		for _, entry := range cpTree.Entries {
316			if entry.Mode != filemode.Dir {
317				continue
318			}
319			if _, err := strconv.Atoi(entry.Name); err != nil {
320				continue
321			}
322			sessionTree, err := cpTree.Tree(entry.Name)
323			if err != nil {
324				continue
325			}
326			transcript, err := readTranscriptFromObjectTree(sessionTree, "")
327			if err != nil || len(transcript) == 0 {
328				continue
329			}
330			if transcriptGen, ok := timestampRangeFromTranscript(transcript); ok {
331				mergeGenerationRange(&gen, &found, transcriptGen)
332			}
333		}
334		return gen, found
335	}
336	
337	// AggregateTranscriptTimestamps derives a generation timestamp envelope from
338	// transcripts already in memory, using the same first/last-event semantics
339	// as ComputeGenerationTimestampsFromTrees but skipping the blob reads.
340	func AggregateTranscriptTimestamps(transcripts [][]byte) (GenerationMetadata, bool) {
341		var gen GenerationMetadata
342		found := false
343		for _, transcript := range transcripts {
344			if len(transcript) == 0 {
345				continue
346			}
347			if r, ok := timestampRangeFromTranscript(transcript); ok {
348				mergeGenerationRange(&gen, &found, r)
349			}
350		}
351		return gen, found
352	}
353	
354	func timestampRangeFromTranscript(transcript []byte) (GenerationMetadata, bool) {
355		reader := bufio.NewReader(bytes.NewReader(transcript))
356		var gen GenerationMetadata
357		found := false
358	
359		for {
360			line, err := reader.ReadBytes('\n')
361			if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
362				var event struct {
363					Timestamp string `json:"timestamp"`
364				}
365				if jsonErr := json.Unmarshal(trimmed, &event); jsonErr == nil && event.Timestamp != "" {
366					if ts, parseErr := time.Parse(time.RFC3339Nano, event.Timestamp); parseErr == nil {
367						MergeGenerationTime(&gen, &found, ts.UTC())
368					}
369				}
370			}
371			if errors.Is(err, io.EOF) {
372				break
373			}
374			if err != nil {
375				break
376			}
377		}
378	
379		return gen, found
380	}
381	
382	func mergeGenerationRange(dst *GenerationMetadata, found *bool, src GenerationMetadata) {
383		MergeGenerationTime(dst, found, src.OldestCheckpointAt)
384		MergeGenerationTime(dst, found, src.NewestCheckpointAt)
385	}
386	
387	// MergeGenerationTime expands the generation timestamp envelope to include ts.
388	// The found flag is set the first time a non-zero timestamp is observed.
389	func MergeGenerationTime(gen *GenerationMetadata, found *bool, ts time.Time) {
390		if ts.IsZero() {
391			return
392		}
393		ts = ts.UTC()
394		if !*found {
395			gen.OldestCheckpointAt = ts
396			gen.NewestCheckpointAt = ts
397			*found = true
398			return
399		}
400		if ts.Before(gen.OldestCheckpointAt) {
401			gen.OldestCheckpointAt = ts
402		}
403		if ts.After(gen.NewestCheckpointAt) {
404			gen.NewestCheckpointAt = ts
405		}
406	}
407	
408	// generationRefWidth is the zero-padded width of archived generation ref names.
409	const generationRefWidth = 13
410	
411	// ArchivedGenerationRefName returns the full ref name for an archived generation number.
412	func ArchivedGenerationRefName(number int) plumbing.ReferenceName {
413		return plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, number))
414	}
415	
416	// GenerationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
417	var GenerationRefPattern = regexp.MustCompile(`^\d{13}$`)
418	
419	// listArchivedGenerations returns the names of all archived generation refs
420	// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
421	func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
422		refs, err := s.repo.References()
423		if err != nil {
424			return nil, fmt.Errorf("failed to list references: %w", err)
425		}
426	
427		var archived []string
428		err = refs.ForEach(func(ref *plumbing.Reference) error {
429			name := ref.Name().String()
430			if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
431				return nil
432			}
433			suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
434			if suffix == "current" || !GenerationRefPattern.MatchString(suffix) {
435				return nil
436			}
437			archived = append(archived, suffix)
438			return nil
439		})
440		if err != nil {
441			return nil, fmt.Errorf("failed to iterate references: %w", err)
442		}
443	
444		sort.Strings(archived)
445		return archived, nil
446	}
447	
448	// NextGenerationNumber returns the next sequential generation number for archiving.
449	// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
450	func (s *V2GitStore) NextGenerationNumber() (int, error) {
451		archived, err := s.ListArchivedGenerations()
452		if err != nil {
453			return 0, err
454		}
455	
456		var maxNum int64
457		for _, name := range archived {
458			n, parseErr := strconv.ParseInt(name, 10, 64)
459			if parseErr != nil {
460				continue // skip unparseable entries
461			}
462			if n > maxNum {
463				maxNum = n
464			}
465		}
466		return int(maxNum) + 1, nil
467	}
468	
469	// RotateCurrentGenerationIfNeeded archives /full/current when it has reached
470	// maxCheckpoints. It returns the archived ref name when this call completes
471	// a rotation.
472	func (s *V2GitStore) RotateCurrentGenerationIfNeeded(ctx context.Context, maxCheckpoints int) (plumbing.ReferenceName, bool, error) {
473		if maxCheckpoints <= 0 {
474			maxCheckpoints = s.maxCheckpoints()
475		}
476	
477		// This is a 2-phase operation:
478		//
479		//  1. Archive: determine the next generation number, create a new ref pointing
480		//     to the current /full/current commit.
481		//  2. Reset: create a fresh orphan commit with an empty tree, point
482		//     /full/current at it.
483		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
484	
485		// Guard against concurrent rotation: re-read /full/current and check if
486		// it's still above the threshold. If not, another instance already rotated.
487		_, currentTreeHash, err := s.GetRefState(refName)
488		if err != nil {
489			return "", false, fmt.Errorf("rotation: failed to read /full/current: %w", err)
490		}
491		checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
492		if err != nil {
493			return "", false, fmt.Errorf("rotation: failed to count checkpoints: %w", err)
494		}
495		if checkpointCount < maxCheckpoints {
496			return "", false, nil
497		}
498	
499		currentRef, err := s.repo.Reference(refName, true)
500		if err != nil {
501			return "", false, fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
502		}
503	
504		archiveNumber, err := s.NextGenerationNumber()
505		if err != nil {
506			return "", false, fmt.Errorf("rotation: failed to determine next generation number: %w", err)
507		}
508	
509		// Phase 1: Prepare archive and reset commits without changing refs yet.
510		// If the archive ref already exists, another instance already rotated — skip.
511		archiveRefName := ArchivedGenerationRefName(archiveNumber)
512		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
513			logging.Info(ctx, "rotation: archive ref already exists, skipping",
514				slog.String("archive_ref", string(archiveRefName)),
515			)
516			return archiveRefName, false, nil
517		}
518	
519		// Write generation.json to the current tree before archiving.
520		gen := s.computeGenerationTimestamps(currentTreeHash)
521		archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
522		if err != nil {
523			return "", false, fmt.Errorf("rotation: failed to add generation.json: %w", err)
524		}
525	
526		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
527		archiveCommitHash, err := CreateCommit(ctx, s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
528		if err != nil {
529			return "", false, fmt.Errorf("rotation: failed to create archive commit: %w", err)
530		}
531	
532		// Create fresh orphan /full/current (empty tree, no generation.json).
533		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
534		if err != nil {
535			return "", false, fmt.Errorf("rotation: failed to build empty tree: %w", err)
536		}
537	
538		orphanCommitHash, err := CreateCommit(ctx, s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
539		if err != nil {
540			return "", false, fmt.Errorf("rotation: failed to create orphan commit: %w", err)
541		}
542	
543		// Verify /full/current hasn't been advanced by another writer since we read it.
544		// If it changed, abort before recording a publication marker.
545		postArchiveRef, err := s.repo.Reference(refName, true)
546		if err != nil {
547			return "", false, fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
548		}
549		if postArchiveRef.Hash() != currentRef.Hash() {
550			logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
551			return archiveRefName, false, nil
552		}
553	
554		publication := PendingV2FullGenerationPublication{
555			ArchiveRefName:           archiveRefName.String(),
556			ArchiveCommitHash:        archiveCommitHash.String(),
557			PreviousFullCurrentHash:  currentRef.Hash().String(),
558			ResetFullCurrentRootHash: orphanCommitHash.String(),
559			QueuedAt:                 time.Now().UTC(),
560		}
561	
562		// The commit objects above are not reachable from the v2 refs yet. Record
563		// the pending publication before moving refs. Pre-push drops stale reset
564		// handoffs until the newest queued reset root is in local /full/current
565		// history, then publishes the queued archive refs together.
566		if err := s.AppendPendingFullGenerationPublication(ctx, publication); err != nil {
567			return "", false, fmt.Errorf("rotation: failed to record pending full rotation: %w", err)
568		}
569		keepPendingPublication := false
570		defer func() {
571			if keepPendingPublication {
572				return
573			}
574			if removeErr := s.RemovePendingFullGenerationPublications(ctx, []PendingV2FullGenerationPublication{publication}); removeErr != nil {
575				logging.Warn(ctx, "rotation: failed to remove pending full rotation after failed rotation",
576					slog.String("error", removeErr.Error()),
577					slog.String("archive_ref", string(archiveRefName)),
578					slog.String("previous_full_current_hash", currentRef.Hash().String()),
579					slog.String("archive_commit_hash", archiveCommitHash.String()),
580					slog.String("reset_full_current_root_hash", orphanCommitHash.String()),
581				)
582			}
583		}()
584	
585		// Phase 2: publish local refs after the pending publication marker exists.
586		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
587			logging.Info(ctx, "rotation: archive ref already exists, skipping",
588				slog.String("archive_ref", string(archiveRefName)),
589			)
590			return archiveRefName, false, nil
591		}
592		archiveRef := plumbing.NewHashReference(archiveRefName, archiveCommitHash)
593		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
594			return "", false, fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
595		}
596	
597		reset, err := s.resetFullCurrentRefIfUnchanged(ctx, refName, postArchiveRef, orphanCommitHash)
598		if err != nil {
599			return "", false, err
600		}
601		if !reset {
602			return archiveRefName, false, nil
603		}
604	
605		keepPendingPublication = true
606		logging.Info(ctx, "generation rotation complete",
607			slog.Int("archived_generation", archiveNumber),
608			slog.String("archive_ref", string(archiveRefName)),
609		)
610	
611		return archiveRefName, true, nil
612	}
613	
614	func (s *V2GitStore) resetFullCurrentRefIfUnchanged(ctx context.Context, refName plumbing.ReferenceName, expectedRef *plumbing.Reference, newHash plumbing.Hash) (bool, error) {
615		newRef := plumbing.NewHashReference(refName, newHash)
616		if err := s.repo.Storer.CheckAndSetReference(newRef, expectedRef); err != nil {
617			if errors.Is(err, storage.ErrReferenceHasChanged) {
618				logging.Info(ctx, "rotation: /full/current changed before reset, leaving current ref intact")
619				return false, nil
620			}
621			return false, fmt.Errorf("rotation: failed to reset /full/current: %w", err)
622		}
623		return true, nil
624	}
625	
626	func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
627		_, _, err := s.RotateCurrentGenerationIfNeeded(ctx, s.maxCheckpoints())
628		return err
629	}
630

