package checkpoint

import (
	"context"
	"testing"

	"github.com/stretchr/testify/require"
)

// The deterministic /full/root commit must produce the same SHA on every
// machine that constructs it. This test pins the SHA so any accidental
// change to the deterministic inputs (author, time, message, encoding) is
// caught immediately. If this test fails after a deliberate change to the
// inputs, update the constant — but understand that doing so creates a
// migration problem: clients running old code will produce a different
// SHA, breaking the "race resolves to no-op" property.
const expectedV2FullRootHash = "c095af40b171ff4c3c4a781abacd39aa499e183b"

func TestBuildV2FullRootCommit_Deterministic(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)

	first, err := BuildV2FullRootCommit(context.Background(), repo)
	require.NoError(t, err)

	second, err := BuildV2FullRootCommit(context.Background(), repo)
	require.NoError(t, err)

	require.Equal(t, first, second,
		"two construction calls must produce the same hash")
}

func TestBuildV2FullRootCommit_WellKnownSHA(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)

	hash, err := BuildV2FullRootCommit(context.Background(), repo)
	require.NoError(t, err)

	require.Equal(t, expectedV2FullRootHash, hash.String(),
		"deterministic root commit SHA changed — see comment on expectedV2FullRootHash")
}

func TestBuildV2FullRootCommit_AcrossDifferentRepos(t *testing.T) {
	t.Parallel()
	repoA := initTestRepo(t)
	repoB := initTestRepo(t)

	hashA, err := BuildV2FullRootCommit(context.Background(), repoA)
	require.NoError(t, err)

	hashB, err := BuildV2FullRootCommit(context.Background(), repoB)
	require.NoError(t, err)

	require.Equal(t, hashA, hashB,
		"different repos must produce identical root commit SHA")
}

